const MapMadagascar = ({ element, active, highlighted, width, onClick, onChange }) => {
  return (
    <ElementWrapper
      element={element}
      onClick={onClick}
      onChange={onChange}
      maxWidth={width}
      active={active}
      highlighted={highlighted}
      resizeHandles={['e']}
      editable
      fit
    >
      <MapMadagascarContent element={element} />
    </ElementWrapper>
  );
};

export const MapMadagascarPresent = ({ element }) => {
  return <MapMadagascarContent element={element} />;
};

